import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long t = nextLong();
        long[] a = new long[n];
        for (int i = 0; i < n; i++) a[i] = nextLong();
        // Jump +2 whenever possible: the spread grows with the last index reached.
        int i = 0;
        long c = 1;
        while (a[i] - a[0] < t) {
            if (i + 2 < n) i += 2;
            else if (i + 1 < n) i += 1;
            else { System.out.println(n); return; }
            c++;
        }
        System.out.println(c);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, t := readInt(), readInt()
	a := make([]int, n)
	for i := range a {
		a[i] = readInt()
	}
	// Jump +2 whenever possible: the spread grows with the last index reached.
	i, c := 0, 1
	for a[i]-a[0] < t {
		if i+2 < n {
			i += 2
		} else if i+1 < n {
			i++
		} else {
			fmt.Println(n)
			return
		}
